```zig
const std = @import("std");

pub fn combinations(buffer: []u9, sum: usize, size: usize, exclude: u9) []const u9 {
    var results: usize = 0;
    for (0..512) |m| {
        const mask: u9 = @intCast(m);
        if (@popCount(mask) == size) {
            if (mask & exclude == 0) {
                var current_sum: usize = 0;
                var mm = mask;
                var i: u4 = 0;
                while (mm != 0) {
                    if (mm & 1 != 0) {
                        current_sum += @as(usize, i + 1);
                    }
                    mm >>= 1;
                    i += 1;
                }
                if (current_sum == sum) {
                    buffer[results] = mask;
                    results += 1;
                }
            }
        }
    }

    std.sort.sort(u9, buffer[0..results], {}, std.sort.asc(u9));

    return buffer[0..results];
}
```

